            { "scan.none.t",    ("Nothing in sights", "Nada en la mira") },
            { "scan.none",      ("Point the reticle at an asteroid, a pod, a planet, a ship or a nebula and tap SCAN.", "Apunta la mira a un asteroide, un pod, un planeta, una nave o una nebulosa y toca ESCANEAR.") },
