            { "laser.off",      ("Weapons are off in this class", "Las armas están apagadas en esta clase") },
            { "scan.asteroid.t", ("Asteroid", "Asteroide") },
            { "scan.asteroid",  ("Rocky leftover from when the planets formed, 4.6 billion years ago. Most orbit between Mars and Jupiter. NASA's OSIRIS-REx brought a sample of asteroid Bennu to Earth in 2023.", "Roca sobrante de cuando se formaron los planetas, hace 4.600 millones de años. La mayoría orbita entre Marte y Júpiter. OSIRIS-REx de la NASA trajo a la Tierra una muestra del asteroide Bennu en 2023.") },
            { "scan.pod.Fuel",  ("Propellant depot: +15% fuel. Real probes can't refuel in space yet: every kilogram is launched from Earth.", "Depósito de propelente: +15% de combustible. Las sondas reales aún no pueden recargar en el espacio: cada kilo sale desde la Tierra.") },
            { "scan.pod.Boost", ("Fills your Burnout bar: a burst of speed that also protects you.", "Llena tu barra de Burnout: un arranque de velocidad que además te protege.") },
            { "scan.pod.Shield", ("Shield for 10 s: ignores crashes and laser hits. Real probes carry Whipple shields against dust impacts.", "Escudo por 10 s: ignora choques y disparos. Las sondas reales llevan escudos Whipple contra impactos de polvo.") },
            { "scan.pod.EMP",   ("Electromagnetic pulse: switches off your rivals' Burnout for 5 s.", "Pulso electromagnético: apaga el Burnout de tus rivales por 5 s.") },
            { "scan.pod.GravityAssist", ("A small gravity kick: free speed, like skimming past a planet.", "Un pequeño empujón gravitatorio: velocidad gratis, como rozar un planeta.") },
            { "scan.planet.mercury", ("Closest to the Sun. One day (sunrise to sunrise) lasts 176 Earth days; the surface swings from -180 °C to 430 °C. Visited by Mariner 10, MESSENGER and BepiColombo.", "El más cercano al Sol. Un día (de amanecer a amanecer) dura 176 días terrestres; la superficie va de -180 °C a 430 °C. Lo visitaron Mariner 10, MESSENGER y BepiColombo.") },
            { "scan.planet.venus",   ("Hottest planet: 465 °C under thick CO2 clouds. It spins backwards, and its day is longer than its year. Magellan mapped it by radar.", "El planeta más caliente: 465 °C bajo nubes espesas de CO2. Gira al revés y su día es más largo que su año. Magellan lo mapeó con radar.") },
            { "scan.planet.earth",   ("Our home and the only world known to have life. 71% of it is covered by water. Every mission starts here.", "Nuestro hogar y el único mundo con vida conocida. El 71% está cubierto de agua. Toda misión empieza aquí.") },
            { "scan.planet.mars",    ("Red from iron oxide dust. Home of Olympus Mons, the tallest volcano in the Solar System. The rovers Curiosity and Perseverance explore it today.", "Rojo por el polvo de óxido de hierro. Allí está el Olympus Mons, el volcán más alto del Sistema Solar. Hoy lo exploran los rovers Curiosity y Perseverance.") },
            { "scan.planet.jupiter", ("Largest planet: 11 Earths wide. The Great Red Spot is a storm bigger than Earth. NASA's Juno orbits it today.", "El planeta más grande: 11 Tierras de ancho. La Gran Mancha Roja es una tormenta más grande que la Tierra. Juno de la NASA lo orbita hoy.") },
            { "scan.planet.saturn",  ("Its rings are ice and rock, up to 280,000 km across but mostly only about 10 m thick. Cassini studied it for 13 years.", "Sus anillos son hielo y roca, de hasta 280.000 km de ancho pero casi siempre de unos 10 m de grosor. Cassini lo estudió durante 13 años.") },
            { "scan.planet.uranus",  ("Tilted 98°: it rolls around the Sun on its side. Only Voyager 2 has visited it, in 1986.", "Inclinado 98°: da vueltas al Sol acostado. Solo Voyager 2 lo ha visitado, en 1986.") },
            { "scan.planet.neptune", ("Windiest planet: up to 2,100 km/h. A radio signal takes about 4 hours to reach Earth. Voyager 2 flew past in 1989.", "El planeta más ventoso: hasta 2.100 km/h. Una señal de radio tarda unas 4 horas en llegar a la Tierra. Voyager 2 pasó en 1989.") },
            { "scan.probe.messenger.t", ("MESSENGER", "MESSENGER") },
            { "scan.probe.messenger",   ("NASA's first Mercury orbiter (2011-2015). It needed six gravity assists (Earth, Venus twice, Mercury three times) to slow down enough.", "El primer orbitador de Mercurio de la NASA (2011-2015). Necesitó seis asistencias gravitatorias (Tierra, Venus dos veces, Mercurio tres) para frenar lo suficiente.") },
            { "scan.probe.magellan.t",  ("Magellan", "Magellan") },
            { "scan.probe.magellan",    ("Mapped 98% of Venus with radar through the clouds (1990-1994).", "Mapeó el 98% de Venus con radar a través de las nubes (1990-1994).") },
            { "scan.probe.mro.t",       ("Mars Reconnaissance Orbiter", "Mars Reconnaissance Orbiter") },
            { "scan.probe.mro",         ("Orbiting Mars since 2006. Its HiRISE camera can see objects the size of a kitchen table, and it relays data from the rovers.", "Orbita Marte desde 2006. Su cámara HiRISE ve objetos del tamaño de una mesa y retransmite los datos de los rovers.") },
            { "scan.probe.juno.t",      ("Juno", "Juno") },
            { "scan.probe.juno",        ("Solar-powered, with 3 panels 9 m long, because sunlight at Jupiter is about 27 times weaker. In orbit since 2016.", "Funciona con energía solar, con 3 paneles de 9 m, porque la luz del Sol en Júpiter es unas 27 veces más débil. En órbita desde 2016.") },
            { "scan.probe.cassini.t",   ("Cassini", "Cassini") },
            { "scan.probe.cassini",     ("Studied Saturn for 13 years (2004-2017) and dropped the Huygens probe on Titan. It ended by diving into Saturn.", "Estudió Saturno 13 años (2004-2017) y soltó la sonda Huygens sobre Titán. Terminó lanzándose dentro de Saturno.") },
            { "scan.probe.voyager.t",   ("Voyager 2", "Voyager 2") },
            { "scan.probe.voyager",     ("Launched in 1977, the only spacecraft to visit Uranus and Neptune. Powered by plutonium (RTG) because the Sun is too faint out here.", "Lanzada en 1977, la única nave que visitó Urano y Neptuno. Funciona con plutonio (RTG) porque aquí el Sol es demasiado débil.") },
            { "scan.probe.hubble.t",    ("Hubble Space Telescope", "Telescopio espacial Hubble") },
            { "scan.probe.hubble",      ("Orbiting Earth since 1990, about 540 km up. Many of the nebulae in this sky are its photos.", "Orbita la Tierra desde 1990, a unos 540 km de altura. Muchas de las nebulosas de este cielo son fotos suyas.") },
            { "scan.probe.jwst.t",      ("James Webb Space Telescope", "Telescopio espacial James Webb") },
            { "scan.probe.jwst",        ("Infrared telescope 1.5 million km from Earth, with a 6.5 m gold mirror and a sunshield the size of a tennis court.", "Telescopio infrarrojo a 1,5 millones de km de la Tierra, con un espejo dorado de 6,5 m y un parasol del tamaño de una cancha de tenis.") },
            { "scan.probe.iss.t",       ("International Space Station", "Estación Espacial Internacional") },
            { "scan.probe.iss",         ("Crewed since 2000. It circles Earth every ~90 minutes at about 28,000 km/h.", "Habitada desde el año 2000. Da la vuelta a la Tierra cada ~90 minutos a unos 28.000 km/h.") },
            { "scan.moon.phobos.t",     ("Phobos", "Fobos") },
            { "scan.moon.phobos",       ("Mars' larger moon, only about 22 km across. It is slowly spiralling in and will break apart in tens of millions of years.", "La luna mayor de Marte, de apenas unos 22 km. Se acerca lentamente y se romperá en decenas de millones de años.") },
            { "scan.moon.io.t",         ("Io", "Ío") },
            { "scan.moon.io",           ("The most volcanic world known: Jupiter's tides squeeze it and heat its inside.", "El mundo más volcánico conocido: las mareas de Júpiter lo aprietan y calientan su interior.") },
            { "scan.moon.europa.t",     ("Europa", "Europa") },
            { "scan.moon.europa",       ("An ocean of salty water lies under its ice shell. NASA's Europa Clipper is on its way to study it.", "Bajo su capa de hielo hay un océano de agua salada. Europa Clipper de la NASA va en camino a estudiarlo.") },
            { "scan.moon.titan.t",      ("Titan", "Titán") },
            { "scan.moon.titan",        ("Bigger than Mercury, with a thick atmosphere and lakes of liquid methane. NASA's Dragonfly drone will fly there.", "Más grande que Mercurio, con atmósfera espesa y lagos de metano líquido. El dron Dragonfly de la NASA volará allí.") },
            { "scan.moon.enceladus.t",  ("Enceladus", "Encélado") },
            { "scan.moon.enceladus",    ("Shoots geysers of water from an ocean under its ice. Cassini flew through them.", "Lanza géiseres de agua desde un océano bajo su hielo. Cassini pasó a través de ellos.") },
            { "scan.moon.miranda.t",    ("Miranda", "Miranda") },
            { "scan.moon.miranda",      ("Has cliffs about 20 km high, some of the tallest in the Solar System. Seen up close only by Voyager 2.", "Tiene acantilados de unos 20 km de altura, de los más altos del Sistema Solar. Solo Voyager 2 la vio de cerca.") },
            { "scan.moon.triton.t",     ("Triton", "Tritón") },
            { "scan.moon.triton",       ("Orbits Neptune backwards, so it was probably captured from the Kuiper Belt. Voyager 2 saw nitrogen geysers on it.", "Orbita a Neptuno al revés, así que probablemente fue capturada del cinturón de Kuiper. Voyager 2 vio géiseres de nitrógeno.") },
            { "scan.flyby",     ("Gravity assist: fly through its blue ring and its gravity swings you out faster, for free.", "Asistencia gravitatoria: pasa por su anillo azul y su gravedad te lanza más rápido, gratis.") },
            { "scan.ship",      ("Hull {0}/3 · fuel {1}%\nSCAN says hi. FIRE costs them a hull point.", "Casco {0}/3 · combustible {1}%\nESCANEAR lo saluda. DISPARAR le quita un punto de casco.") },
            { "scan.sky.nebula.t",    ("Nebula", "Nebulosa") },
            { "scan.sky.nebula",      ("A cloud of gas and dust where stars are born, or where a star died. Its colours come from glowing hydrogen, oxygen and sulfur.", "Una nube de gas y polvo donde nacen estrellas, o donde murió una. Sus colores vienen del hidrógeno, oxígeno y azufre brillando.") },
            { "scan.sky.galaxy.t",    ("Galaxy", "Galaxia") },
            { "scan.sky.galaxy",      ("Billions of stars held together by gravity. Our Milky Way is one; the nearest big neighbour, Andromeda, is 2.5 million light-years away.", "Miles de millones de estrellas unidas por la gravedad. La Vía Láctea es una; la gran vecina más cercana, Andrómeda, está a 2,5 millones de años luz.") },
            { "scan.sky.blackhole.t", ("Black hole", "Agujero negro") },
            { "scan.sky.blackhole",   ("So much mass in so little space that not even light escapes. In 2019 the Event Horizon Telescope photographed the one in galaxy M87.", "Tanta masa en tan poco espacio que ni la luz escapa. En 2019 el Event Horizon Telescope fotografió el de la galaxia M87.") },
            { "scan.sky.nebula_01.t", ("Orion Nebula", "Nebulosa de Orión") },
            { "scan.sky.nebula_01",   ("A stellar nursery 1,344 light-years away, visible to the naked eye below Orion's belt. Image: Hubble.", "Una guardería de estrellas a 1.344 años luz, visible a simple vista bajo el cinturón de Orión. Imagen: Hubble.") },
            { "scan.sky.nebula_02.t", ("Helix Nebula", "Nebulosa de la Hélice") },
            { "scan.sky.nebula_02",   ("The glowing shell of a dying Sun-like star, 650 light-years away. Our Sun will end like this in about 5 billion years. Image: Spitzer.", "La cáscara brillante de una estrella como el Sol que muere, a 650 años luz. Nuestro Sol terminará así en unos 5.000 millones de años. Imagen: Spitzer.") },
            { "scan.sky.nebula_03.t", ("Carina Nebula", "Nebulosa de Carina") },
            { "scan.sky.nebula_03",   ("One of the largest star-forming regions in our galaxy, 7,500 light-years away.", "Una de las regiones de formación de estrellas más grandes de nuestra galaxia, a 7.500 años luz.") },
            { "scan.sky.nebula_04.t", ("Pillars of Creation", "Pilares de la Creación") },
            { "scan.sky.nebula_04",   ("Towers of gas in the Eagle Nebula, light-years tall, where new stars are forming. Made famous by Hubble in 1995.", "Torres de gas en la Nebulosa del Águila, de años luz de altura, donde se forman estrellas nuevas. Hubble las hizo famosas en 1995.") },
            { "scan.sky.nebula_05.t", ("Ring Nebula", "Nebulosa del Anillo") },
            { "scan.sky.nebula_05",   ("Gas thrown off by a dying star, about 2,500 light-years away in the constellation Lyra.", "Gas expulsado por una estrella moribunda, a unos 2.500 años luz, en la constelación de la Lira.") },
            { "scan.sky.nebula_06.t", ("Horsehead Nebula", "Nebulosa Cabeza de Caballo") },
            { "scan.sky.nebula_06",   ("A dark cloud of dust shaped like a horse's head, 1,375 light-years away in Orion.", "Una nube oscura de polvo con forma de cabeza de caballo, a 1.375 años luz, en Orión.") },
            { "scan.sky.galaxy_01.t", ("Andromeda Galaxy", "Galaxia de Andrómeda") },
            { "scan.sky.galaxy_01",   ("The nearest large galaxy: 2.5 million light-years away, about a trillion stars. It will merge with the Milky Way in about 4.5 billion years.", "La galaxia grande más cercana: a 2,5 millones de años luz, con cerca de un billón de estrellas. Se fusionará con la Vía Láctea en unos 4.500 millones de años.") },
            { "scan.sky.galaxy_02.t", ("Whirlpool Galaxy (M51)", "Galaxia del Remolino (M51)") },
            { "scan.sky.galaxy_02",   ("A spiral galaxy 31 million light-years away, pulling on a small companion galaxy.", "Una galaxia espiral a 31 millones de años luz que tira de una pequeña galaxia compañera.") },
            { "scan.sky.galaxy_03.t", ("Hubble Deep Field", "Campo Profundo del Hubble") },
            { "scan.sky.galaxy_03",   ("Almost every dot is a galaxy: a tiny patch of sky holding thousands of them, some seen as they were over 10 billion years ago.", "Casi cada punto es una galaxia: un pedacito de cielo con miles de ellas, algunas vistas como eran hace más de 10.000 millones de años.") },
            { "scan.sky.blackhole_01.t", ("M87* black hole", "Agujero negro M87*") },
            { "scan.sky.blackhole_01",   ("The first black hole ever photographed (Event Horizon Telescope, 2019): 6.5 billion times the Sun's mass, 55 million light-years away.", "El primer agujero negro fotografiado (Event Horizon Telescope, 2019): 6.500 millones de veces la masa del Sol, a 55 millones de años luz.") },
            { "podname.Fuel",          ("FUEL", "COMBUSTIBLE") },
