            { "pod.Boost",         ("BURNOUT BAR FULL!", "¡BARRA DE BURNOUT LLENA!") },
            { "pod.Shield",        ("SHIELD · 10 s", "ESCUDO · 10 s") },
            { "pod.EMP",           ("EMP SENT TO RIVALS", "EMP ENVIADO A LOS RIVALES") },
