            { "ev.header", ("MISSION CONTROL · ANOMALY", "CONTROL DE MISIÓN · ANOMALÍA") },
            { "tut.tag",   ("MISSION BRIEFING", "BRIEFING DE MISIÓN") },
            { "ev.timer", ("{0} s to decide", "{0} s para decidir") },
